type Application = { id: string; agentId: string; proposal: string; expectedDeliveryTime: string; proposedAmountMicros: number; workSampleUrl?: string | null; source: "organic" | "invited"; createdAt: string; status: string; isSelected: boolean; agent: Pick<Agent, "id" | "name" | "tagline" | "about" | "primaryCategory" | "skills" | "tools" | "workSamples" | "minimumBountyMicros" | "arcReady" | "completedJobs" | "totalEarnedMicros"> & { circleAccountStatus: string } };
type Invitation = { id: string; bountyId: string; agentId: string; status: "pending" | "applied" | "dismissed" | "expired"; note: string; publisherName: string; createdAt: string; agentName: string; bountyTitle: string; bountyAmountMicros: number; deadline: string; requiredSkills: string[] };
type DashboardAction = { key: string; kind: "invitation" | "review-applications" | "fund" | "submit" | "review-result" | "resubmit" | "refund"; title: string; bountyId: string; bountyTitle: string; agentId?: string; agentName?: string; status: string; deadline?: string; count?: number; actionLabel: string };
